```tsx
import type { ReactNode } from "react";
import "./ButtonRow.css";

export interface ButtonRowProps {
  primaryLabel: string;
  onPrimary: () => void;
  primaryDisabled?: boolean;
  secondaryLabel: string;
  onSecondary: () => void;
  secondaryDisabled?: boolean;
  quietLabel: string;
  onQuiet: () => void;
  quietDisabled?: boolean;
}

export function ButtonRow({
  primaryLabel,
  onPrimary,
  primaryDisabled = false,
  secondaryLabel,
  onSecondary,
  secondaryDisabled = false,
  quietLabel,
  onQuiet,
  quietDisabled = false,
}: ButtonRowProps): ReactNode {
  return (
    <div className="button-row">
      <button
        type="button"
        className="button-row__btn button-row__btn--primary"
        onClick={onPrimary}
        disabled={primaryDisabled}
      >
        {primaryLabel}
      </button>
      <button
        type="button"
        className="button-row__btn button-row__btn--secondary"
        onClick={onSecondary}
        disabled={secondaryDisabled}
      >
        {secondaryLabel}
      </button>
      <button
        type="button"
        className="button-row__btn button-row__btn--quiet"
        onClick={onQuiet}
        disabled={quietDisabled}
      >
        {quietLabel}
      </button>
    </div>
  );
}
```

```css
.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: clamp(0.5rem, 1.5vw, 1rem);
}

.button-row__btn {
  font: inherit;
  font-size: clamp(0.9rem, 1.2vw, 1.05rem);
  font-weight: 600;
  line-height: 1;
  min-height: 2.75rem;
  padding: 0.7rem 1.25rem;
  border: 1px solid var(--ink);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease;
}

.button-row__btn--primary {
  border-color: var(--myelin);
  background: var(--myelin);
  color: var(--slide);
}

.button-row__btn--primary:hover:not(:disabled) {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--slide);
}

.button-row__btn--secondary:hover:not(:disabled) {
  background: var(--myelin-wash);
}

.button-row__btn--quiet {
  border-color: transparent;
  padding-inline: 0.75rem;
}

.button-row__btn--quiet:hover:not(:disabled) {
  text-decoration: underline;
  text-underline-offset: 0.25em;
}

.button-row__btn:disabled {
  cursor: not-allowed;
  color: var(--muted);
  border-color: var(--muted);
  background: transparent;
}

.button-row__btn--quiet:disabled {
  border-color: transparent;
}

:root[data-motion="reduce"] .button-row__btn {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .button-row__btn {
    transition: none;
  }
}
